ValidationRule.errorConditionFormula:
AND( $Profile.Name <>'Integration User', $Profile.Name <>'Data Migration', $Setup.NSP_Trigger_Switch__c.ContactValidations__c = false,
OR ( AND ( ISNEW(), NOT(ISNULL(NSP_SSN__c )) ), ISCHANGED(NSP_SSN__c ) ), NOT( OR( LEN ( NSP_SSN__c ) = 0, REGEX( NSP_SSN__c , "[0-9]{3}-[0-9]{2}-[0-9]{4}")
) ) )
